def compress_context(anchors: list[str], chunks: list[list[tuple[str, float]]], budget_tokens: int) -> str:
    anchor_text = '\n'.join(anchors)
    anchor_tokens = sum(len(a.split()) for a in anchors)
    remaining = max(0, budget_tokens - anchor_tokens)
    if remaining == 0:
        return anchor_text

    scored = []
    for idx, chunk in enumerate(chunks):
        start = 64 if idx > 0 and len(chunk) > 64 else 0
        for pos, (tok, salience) in enumerate(chunk[start:], start=len(scored)):
            scored.append((pos, tok, salience))

    if len(scored) <= remaining:
        return anchor_text + '\n' + ' '.join(t for _, t, _ in scored)

    threshold = sorted((s for _, _, s in scored), reverse=True)[remaining - 1]
    kept = [t for _, t, s in scored if s >= threshold][:remaining]
    return anchor_text + '\n' + ' '.join(kept)
